package com.ruoyi.paicli.service;

import com.ruoyi.paicli.domain.*;
import com.ruoyi.paicli.configuration.PcProperties;
import com.ruoyi.system.secret.ManagedSecretService;
import org.springframework.transaction.annotation.Transactional;
import java.util.*;

/** 微信bridge使用独立短期用途凭证；文字会话、预算、游标仍以中心为准。 */
public class PcWechatService {
    private final PcStore store;private final PcAccess access;private final PcIdempotency idem;private final PcCrypto crypto;private final PcToolService tools;private final PcSessionService sessions;private final PcCommandService commands;private final PcEvidence evidence;private final ManagedSecretService secrets;private final PcProperties properties;private final PcConnectionService connections;
    public PcWechatService(PcStore s,PcAccess a,PcIdempotency i,PcCrypto c,PcToolService t,PcSessionService ss,PcCommandService cmd,PcEvidence e,ManagedSecretService sec,PcProperties p){this(s,a,i,c,t,ss,cmd,e,sec,p,null);}
    public PcWechatService(PcStore s,PcAccess a,PcIdempotency i,PcCrypto c,PcToolService t,PcSessionService ss,PcCommandService cmd,PcEvidence e,ManagedSecretService sec,PcProperties p,PcConnectionService conn){store=s;access=a;idem=i;crypto=c;tools=t;sessions=ss;commands=cmd;evidence=e;secrets=sec;properties=p;connections=conn;}
    @Transactional("paicliTransactionManager")
    public Map<String,Object> account(PcRunnerPrincipal actor,String key,Map<String,Object> input){return idem.run("runner:"+actor.runnerId()+":wechat-account",key,input,()->{
        PcRecord task=tools.consumedControl(actor,input,"WECHAT_SETUP"),binding=bindingForTask(task,input);String token=PcJson.text(input,"token"),accountId=PcJson.text(input,"accountId"),baseUrl=PcJson.text(input,"baseUrl");if(token.isBlank()||token.length()>8192||accountId.isBlank()||accountId.length()>256||!baseUrl.equals("https://ilinkai.weixin.qq.com"))throw PcException.invalid("微信账号凭证或官方服务地址非法");
        String alias="platform.paicli.wechat."+binding.getId();Long expected=null;try{expected=secrets.metadata("PLATFORM",alias).rowVersion();}catch(IllegalArgumentException ignored){}
        secrets.put("PLATFORM",alias,"paicli","wechat","ilink","bearer","PaiCLI微信账号",token,"用户批准的微信扫码账号保存",expected,String.valueOf(task.getOwnerId()));Map<String,Object> p=store.data(binding);p.put("secretRef",alias);p.put("accountId",accountId);p.put("baseUrl",baseUrl);p.put("syncBuf","");binding.setState(p.containsKey("senderHash")?"BOUND":"LOGIN_REQUIRED");store.save(PcTable.WECHAT_BINDING,binding,p);evidence.audit(binding.getDirectoryContextId(),task.getOwnerId(),task.getId(),task.getSessionId(),"WECHAT_ACCOUNT","STORED",Map.of("configId",binding.getId(),"accountHash",PcJson.digest(accountId)));return Map.of("stored",true,"configId",String.valueOf(binding.getId()),"configVersion",p.getOrDefault("configurationVersion",binding.getVersion()));
    });}
    @Transactional("paicliTransactionManager")
    public Map<String,Object> context(PcRunnerPrincipal actor,String key,Map<String,Object> input){return idem.run("runner:"+actor.runnerId()+":wechat-channel",key,input,()->{
        PcRecord binding;if(actor.kind().equals("WECHAT"))binding=channel(actor,input);else{PcRecord task=tools.consumedControl(actor,input,"WECHAT_START","WECHAT_RESTART","WECHAT_RESUME","WECHAT_SETUP");binding=bindingForTask(task,input);}
        Map<String,Object> p=store.data(binding);long owner=p.containsKey("boundUserId")?PcJson.number(p,"boundUserId"):binding.getOwnerId();access.directory(binding.getDirectoryContextId(),owner,false);String ref=PcJson.text(p,"secretRef");if(!ref.equals("platform.paicli.wechat."+binding.getId()))throw new PcException(503,"PC_WECHAT_LOGIN_REQUIRED","微信账号尚未完成扫码保存");String token=secrets.require("PLATFORM",ref);
        p.putIfAbsent("channelVersion",binding.getVersion());p.putIfAbsent("configurationVersion",p.get("channelVersion"));store.save(PcTable.WECHAT_BINDING,binding,p);long channelVersion=PcJson.number(p,"channelVersion");PcRecord device=store.require(PcTable.RUNNER,actor.runnerId(),true);long administration=store.data(device).get("administrationVersion") instanceof Number n?n.longValue():1;if(device.getState().equals("REVOKED")||administration!=actor.runnerVersion())throw PcException.deny("Runner身份已经撤销");
        if(actor.kind().equals("WECHAT")){PcRecord old=store.require(PcTable.RUNNER_CREDENTIAL,actor.credentialId(),true);old.setState("REVOKED");store.save(PcTable.RUNNER_CREDENTIAL,old,store.data(old));}
        String bridge=crypto.token("pcw_");PcRecord credential=store.insert(PcTable.RUNNER_CREDENTIAL,binding.getDirectoryContextId(),owner,binding.getId(),null,actor.runnerId(),"WECHAT","ACTIVE",PcJson.digest(bridge),Map.of("administrationVersion",administration,"configVersion",channelVersion));credential.setExpiresAt(store.clock.instant().plusSeconds(properties.getDeviceSessionSeconds()));store.save(PcTable.RUNNER_CREDENTIAL,credential,store.data(credential));Map<String,Object> account=new LinkedHashMap<>();account.put("token",token);account.put("accountId",p.get("accountId"));account.put("baseUrl",p.get("baseUrl"));account.put("boundUserId",String.valueOf(owner));account.put("directoryContextId",String.valueOf(binding.getDirectoryContextId()));account.put("syncBuf",p.getOrDefault("syncBuf",""));return Map.of("channelId",String.valueOf(credential.getId()),"bridgeKey",bridge,"expiresAt",credential.getExpiresAt().toString(),"configVersion",channelVersion,"senderHash",PcJson.text(p,"senderHash"),"policy",PcConnectionService.wechatPolicy(p.get("policy") instanceof Map<?,?>?PcJson.object(p,"policy"):Map.of()),"account",account);
    });}
    private PcRecord bindingForTask(PcRecord task,Map<String,Object> input){Map<String,Object> args=PcJson.object(store.data(task),"arguments");long id=PcJson.number(input,"configId");if(id!=PcJson.number(args,"configId"))throw PcException.deny("微信配置不是任务绑定对象");PcRecord binding=store.require(PcTable.WECHAT_BINDING,id,true);if(!Objects.equals(task.getDirectoryContextId(),binding.getDirectoryContextId())||!Objects.equals(task.getOwnerId(),binding.getOwnerId()))throw PcException.deny("微信配置scope不属于控制任务");long configVersion=store.data(binding).get("configurationVersion") instanceof Number n?n.longValue():binding.getVersion();if(configVersion!=PcJson.number(input,"configVersion"))throw PcException.conflict("微信配置定义版本已经改变");return binding;}
    private long bindingVersion(PcRecord binding){Object value=store.data(binding).get("channelVersion");return value instanceof Number n?n.longValue():binding.getVersion();}
    private PcRecord channel(PcRunnerPrincipal actor,Map<String,Object> input){if(!actor.kind().equals("WECHAT")||PcJson.number(input,"channelId")!=actor.credentialId())throw PcException.deny("微信通道身份不匹配");PcRecord device=store.require(PcTable.RUNNER,actor.runnerId(),true);long administration=store.data(device).get("administrationVersion") instanceof Number n?n.longValue():1;if(device.getState().equals("REVOKED")||administration!=actor.runnerVersion())throw PcException.deny("Runner已撤销");PcRecord credential=store.require(PcTable.RUNNER_CREDENTIAL,actor.credentialId(),true);if(!credential.getState().equals("ACTIVE")||!credential.getExpiresAt().isAfter(store.clock.instant()))throw PcException.deny("微信通道已经失效");PcRecord binding=store.require(PcTable.WECHAT_BINDING,credential.getParentId(),true);if(bindingVersion(binding)!=PcJson.number(store.data(credential),"configVersion")||bindingVersion(binding)!=PcJson.number(input,"configVersion")||!Set.of("BOUND","RUNNING","LOGIN_REQUIRED","PAUSED").contains(binding.getState()))throw PcException.deny("微信绑定配置已经改变");access.directory(binding.getDirectoryContextId(),actor.ownerId(),false);return binding;}
    @Transactional("paicliTransactionManager")
    public Map<String,Object> turn(PcRunnerPrincipal actor,String key,Map<String,Object> input){return idem.run("wechat:"+actor.credentialId()+":turn",key,input,()->{
        PcRecord binding=channel(actor,input);Map<String,Object> p=store.data(binding);if(!Objects.equals(PcJson.text(input,"senderHash"),p.get("senderHash"))||PcJson.number(p,"boundUserId")!=actor.ownerId())throw PcException.deny("微信sender未绑定当前若依用户");String messageId=PcJson.text(input,"messageId");if(messageId.isBlank()||messageId.length()>256)throw PcException.invalid("微信消息ID非法");
        if(binding.getState().equals("PAUSED"))throw PcException.conflict("微信通道已暂停，请先恢复再提交文字任务");String unique="wechat:"+binding.getId()+":"+PcJson.digest(messageId);PcRecord previous=store.mapper.findKey(PcTable.TURN,unique,true);if(previous!=null){if(!Objects.equals(store.data(previous).get("input"),input.get("text")))throw PcException.conflict("微信消息ID已用于不同内容");return Map.of("sessionId",String.valueOf(previous.getSessionId()),"taskId",store.data(previous).get("wechatTaskId"),"version",1);}
        String day=store.clock.instant().atZone(java.time.ZoneOffset.UTC).toLocalDate().toString();if(!day.equals(p.get("budgetDay"))){p.put("budgetDay",day);p.put("dailyUsed",0L);p.put("dailyTurnUsed",0L);}Map<String,Object> policy=PcConnectionService.wechatPolicy(p.get("policy") instanceof Map<?,?>?PcJson.object(p,"policy"):Map.of());if(PcJson.number(p,"dailyUsed")>=PcJson.number(p,"dailyBudget"))throw new PcException(429,"PC_WECHAT_BUDGET","微信每日Token额度已用尽");if(PcJson.number(p,"dailyTurnUsed")>=PcJson.number(policy,"dailyTurnLimit"))throw new PcException(429,"PC_WECHAT_TURN_LIMIT","微信每日轮次数已用尽");
        long sessionId;if(p.get("sessionId")!=null)sessionId=PcJson.number(p,"sessionId");else{long model=wechatModel(binding,p);Map<String,Object> created=sessions.create(actor.ownerId(),"wechat-session-"+binding.getId(),Map.of("directoryContextId",binding.getDirectoryContextId(),"runnerId",actor.runnerId(),"modelId",model,"title","微信文字会话","mode","REACT","approvalMode","ASK"));sessionId=PcJson.number(created,"id");p.put("sessionId",String.valueOf(sessionId));}
        PcRecord session=store.require(PcTable.SESSION,sessionId,true);Map<String,Object> response=sessions.submitWechat(session,actor.ownerId(),Map.of("text",PcJson.text(input,"text")));PcRecord task=store.require(PcTable.TASK,PcJson.number(response,"taskId"),false),turn=store.require(PcTable.TURN,task.getParentId(),true);turn.setUniqueKey(unique);Map<String,Object> tp=store.data(turn);tp.put("wechatTaskId",response.get("taskId"));store.save(PcTable.TURN,turn,tp);Map<String,Object> taskPayload=store.data(task);taskPayload.put("wechatBindingId",String.valueOf(binding.getId()));taskPayload.put("wechatConfigVersion",bindingVersion(binding));taskPayload.put("wechatPolicy",policy);Map<String,Object> workspacePolicy=store.data(store.ownerPolicy(binding.getOwnerId(),false));taskPayload.put("taskTokenBudget",Math.min(PcJson.number(workspacePolicy,"taskTokenBudget"),Math.min(PcJson.number(policy,"singleTurnTokenBudget"),PcJson.number(p,"dailyBudget")-PcJson.number(p,"dailyUsed"))));store.save(PcTable.TASK,task,taskPayload);p.put("dailyTurnUsed",PcJson.number(p,"dailyTurnUsed")+1);binding.setState("RUNNING");store.save(PcTable.WECHAT_BINDING,binding,p);response=new LinkedHashMap<>(response);response.put("version",task.getVersion());response.put("sessionId",String.valueOf(sessionId));response.put("configVersion",bindingVersion(binding));return response;
    });}
    private long wechatModel(PcRecord binding,Map<String,Object> data){if(data.get("modelId")!=null){long id=PcJson.number(data,"modelId");sessions.model(id,binding.getDirectoryContextId(),PcJson.number(data,"boundUserId"),false);return id;}PcRecord workspace=store.require(PcTable.DIRECTORY_CONTEXT,binding.getDirectoryContextId(),false);Map<String,Object> wd=store.data(workspace);if(wd.get("defaultProviderId")==null)throw new PcException(503,"PC_WECHAT_MODEL","微信绑定须明确模型，或登记目录默认供应商及其默认模型");PcRecord provider=store.require(PcTable.PROVIDER_CONFIG,PcJson.number(wd,"defaultProviderId"),false);String model=PcJson.text(store.data(provider),"model");var choices=store.mapper.list(PcTable.MODEL_CONFIG,binding.getDirectoryContextId(),null,null,null).stream().filter(m->Objects.toString(store.data(m).get("providerId"),"").equals(String.valueOf(provider.getId()))&&model.equals(store.data(m).get("modelId"))&&Boolean.TRUE.equals(store.data(m).get("enabled"))).toList();if(choices.size()!=1)throw new PcException(503,"PC_WECHAT_MODEL","目录默认供应商模型未明确登记启用");return choices.get(0).getId();}
    private long selectedModel(PcRecord binding,long user,String selector){List<Map<String,Object>> models=connections.list("models",user,binding.getDirectoryContextId());var direct=models.stream().filter(m->Boolean.TRUE.equals(m.get("enabled"))&&(selector.equals(m.get("id"))||selector.equals(m.get("modelId")))).toList();if(direct.size()==1)return PcJson.number(direct.get(0),"id");if(direct.size()>1)throw PcException.invalid("模型名称有歧义，请使用中心模型ID");var providers=connections.list("providers",user,binding.getDirectoryContextId()).stream().filter(p->selector.equals(p.get("provider"))||selector.equals(p.get("id"))).toList();if(providers.size()!=1)throw PcException.invalid("模型或供应商未明确登记");Map<String,Object> provider=providers.get(0);var selected=models.stream().filter(m->Boolean.TRUE.equals(m.get("enabled"))&&Objects.equals(m.get("providerId"),provider.get("id"))&&Objects.equals(m.get("modelId"),provider.get("model"))).toList();if(selected.size()!=1)throw PcException.invalid("供应商默认启动模型未明确登记启用");return PcJson.number(selected.get(0),"id");}
    @Transactional("paicliTransactionManager")
    public Map<String,Object> events(PcRunnerPrincipal actor,Map<String,Object> input){PcRecord binding=channel(actor,input);PcRecord task=access.resource(PcTable.TASK,PcJson.number(input,"taskId"),actor.ownerId(),true,false);if(!Objects.equals(store.data(task).get("wechatBindingId"),String.valueOf(binding.getId())))throw PcException.deny("任务不属于微信通道");return sessions.taskEvents(task.getId(),actor.ownerId(),PcJson.number(input,"after"),null,input.containsKey("limit")?(int)PcJson.number(input,"limit"):200);}
    @Transactional("paicliTransactionManager")
    public Map<String,Object> cursor(PcRunnerPrincipal actor,String key,Map<String,Object> input){return idem.run("wechat:"+actor.credentialId()+":cursor",key,input,()->{PcRecord binding=channel(actor,input);String buf=PcJson.text(input,"syncBuf");if(buf.length()>65536)throw PcException.invalid("微信游标超限");Map<String,Object> p=store.data(binding);p.put("syncBuf",buf);store.save(PcTable.WECHAT_BINDING,binding,p);return Map.of("stored",true,"configVersion",bindingVersion(binding));});}
    @Transactional("paicliTransactionManager")
    public Map<String,Object> commands(PcRunnerPrincipal actor,String key,Map<String,Object> input){return idem.run("wechat:"+actor.credentialId()+":command",key,input,()->{PcRecord binding=channel(actor,input);Map<String,Object> p=store.data(binding);if(!PcJson.text(input,"senderHash").equals(p.get("senderHash")))throw PcException.deny("微信sender不匹配");String name=PcJson.text(input,"name");if(name.equals("resume")){if(!binding.getState().equals("PAUSED")&&!binding.getState().equals("RUNNING"))throw PcException.conflict("仅暂停或运行通道可恢复");binding.setState("RUNNING");store.save(PcTable.WECHAT_BINDING,binding,p);return Map.of("status","RUNNING","message","微信中心通道已恢复");}if(Set.of("pause","stop").contains(name)){binding.setState(name.equals("pause")?"PAUSED":"STOPPED");store.save(PcTable.WECHAT_BINDING,binding,p);for(PcRecord task:store.mapper.list(PcTable.TASK,binding.getDirectoryContextId(),actor.ownerId(),null,null))if(!PcSessionService.terminal(task.getState())&&Objects.toString(store.data(task).get("wechatBindingId"),"").equals(String.valueOf(binding.getId())))sessions.cancel(task.getId(),actor.ownerId(),task.getVersion(),key+":cancel:"+task.getId());return Map.of("status",binding.getState());}if(!Set.of("help","status","cancel","clear","compact","model","cwd","send").contains(name))throw PcException.deny("微信仅开放文字与有限会话命令");if(name.equals("send"))return turn(actor,"wechat-command-send-"+PcJson.digest(key),input);if(name.equals("cwd"))return Map.of("rootPath",store.data(store.require(PcTable.DIRECTORY_CONTEXT,binding.getDirectoryContextId(),false)).get("rootPath"));if(name.equals("help"))return Map.of("commands",List.of("help","status","cwd","send","cancel","clear","compact","model","pause","resume","stop"));if(p.get("sessionId")==null){if(name.equals("status"))return Map.of("status",binding.getState(),"sessionId","","dailyUsed",p.getOrDefault("dailyUsed",0),"dailyTurnUsed",p.getOrDefault("dailyTurnUsed",0));throw PcException.conflict("请先提交文字会话");}PcRecord session=store.require(PcTable.SESSION,PcJson.number(p,"sessionId"),false);if(name.equals("cancel")){var active=store.mapper.list(PcTable.TASK,binding.getDirectoryContextId(),actor.ownerId(),null,null).stream().filter(t->Objects.equals(t.getSessionId(),session.getId())&&!PcSessionService.terminal(t.getState())).toList();if(active.isEmpty())return Map.of("status","IDLE");return sessions.cancel(active.get(0).getId(),actor.ownerId(),active.get(0).getVersion(),key+":cancel");}if(name.equals("clear")||name.equals("compact"))return sessions.contextAction(session.getId(),actor.ownerId(),session.getVersion(),key+":context",name.equals("clear")?"CLEAR":"COMPRESS");if(name.equals("model")&&!PcJson.text(input,"arguments").isBlank()){if(connections==null)throw PcException.conflict("模型切换服务未装配");return connections.switchModel(session.getId(),actor.ownerId(),key+":model",session.getVersion(),selectedModel(binding,actor.ownerId(),PcJson.text(input,"arguments")));}if(name.equals("model"))return Map.of("models",store.mapper.list(PcTable.MODEL_CONFIG,binding.getDirectoryContextId(),null,null,null).stream().map(store::view).toList());if(name.equals("help"))return Map.of("commands",List.of("help","status","send","cancel","clear","compact","model","pause","resume","stop"));return sessions.detail(session.getId(),actor.ownerId());});}
}
